declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('projects.manage');$pdo=db();$projectId=(int)($_GET['project_id']??$_POST['project_id']??0);$p=pm_fetch_project($pdo,$projectId);$pageTitle='Nuevo hito';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));if($name==='')$errors[]='Nombre obligatorio.';if(!$errors){$pdo->prepare('INSERT INTO project_milestones(project_id,name,description,due_date,status,sort_order,created_by) VALUES (?,?,?,?,?,?,?)')->execute([$projectId,$name,trim((string)($_POST['description']??''))?:null,($_POST['due_date']??'')?:null,(string)($_POST['status']??'pending'),(int)($_POST['sort_order']??0),(int)$_SESSION['user_id']]);flash('success','Hito creado.');redirect('project_view.php?id='.$projectId);}}require __DIR__.'/includes/header.php';echo pm_project_tabs($projectId,'summary');?><?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><h2>Nuevo hito · <?=e($p['name'])?></h2><a class="btn btn-light btn-small" href="project_view.php?id=<?=$projectId?>">Volver</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="project_id" value="<?=$projectId?>"><label class="full">Nombre *<input name="name" required></label><label>Fecha objetivo<input type="date" name="due_date"></label><label>Estado<select name="status"><option value="pending">Pendiente</option><option value="in_progress">En progreso</option><option value="completed">Completado</option></select></label><label>Orden<input type="number" name="sort_order" value="0"></label><label class="full">Descripción<textarea name="description"></textarea></label><div class="full form-actions"><button class="btn btn-primary">CREAR HITO</button></div></div></form><?php require __DIR__.'/includes/footer.p